document.addEventListener("click",(function(t){var i=t.target.closest("[data-notifier-send-id]");if(i){var e=parseInt(i.dataset.notifierSendId,10),n=(i.dataset.notifierSendConfirm||"").replace(/\\n/g,"\n");confirm(n)&&Craft.postActionRequest("notifier/notifications/send-report",{notificationId:e},(function(t,i){"success"===i?t.success?Craft.cp.displaySuccess(t.message):Craft.cp.displayError(t.message||Craft.t("notifier","Notification was not sent. Check the Notification Log for details.")):Craft.cp.displayError(Craft.t("notifier","Notification was not sent. Check the Notification Log for details."))}))}}));